INSERT INTO scans (id,owner_id,status,source,image_key,image_content_type,image_bytes,image_width,image_height,problem_text,created_at,updated_at,confirmed_at,questions_json) VALUES ('87019dd8-bccb-449c-913b-53619dd71273','57bd23d6826d75c0bb806b0540cf6866bd607e325243e246cbee905c7b52d98a','confirmed','library','game-theory-02/no-upload/87019dd8-bccb-449c-913b-53619dd71273','image/png',1,1,1,'Câu 1 (2 điểm). Cho phương trình $x^2 - 2(m + 1)x + 2m = 0$ (m là tham số).

a) Chứng minh rằng với mọi m phương trình luôn có hai nghiệm phân biệt $x_1, x_2$.

b) Chứng minh $x_1^4 + x_2^4 > \frac{9}{2}$.

c) Chứng minh $(x_1 + \sqrt{x_1^2 + 1}) (x_2 + \sqrt{x_2^2 + 1}) = 1$ khi và chỉ khi $m = -1$.','2026-10-12T06:27:53.216263+00:00','2026-10-12T06:27:53.216263+00:00','2026-10-12T06:27:53.216263+00:00','[{"id": "q1", "label": "Câu 1", "text": "Câu 1 (2 điểm). Cho phương trình $x^2 - 2(m + 1)x + 2m = 0$ (m là tham số).\n\na) Chứng minh rằng với mọi m phương trình luôn có hai nghiệm phân biệt $x_1, x_2$.\n\nb) Chứng minh $x_1^4 + x_2^4 > \\frac{9}{2}$.\n\nc) Chứng minh $(x_1 + \\sqrt{x_1^2 + 1}) (x_2 + \\sqrt{x_2^2 + 1}) = 1$ khi và chỉ khi $m = -1$."}]');
INSERT INTO scans (id,owner_id,status,source,image_key,image_content_type,image_bytes,image_width,image_height,problem_text,created_at,updated_at,confirmed_at,questions_json) VALUES ('91fc54cb-7f0c-47da-9fdf-deb8053f3301','57bd23d6826d75c0bb806b0540cf6866bd607e325243e246cbee905c7b52d98a','confirmed','library','game-theory-02/no-upload/91fc54cb-7f0c-47da-9fdf-deb8053f3301','image/png',1,1,1,'Câu 2 (1.5 điểm). Người ta muốn ghi bốn số thực ở bốn đỉnh của hình vuông $ABCD$ (mỗi đỉnh một số) thỏa mãn:

i) Bốn số được ghi là đối một phân biệt;

ii) Tổng hai số được ghi ở hai đầu của cạnh $AB$ là 0;

iii) Tổng hai số được ghi ở hai đầu của ba cạnh còn lại là ba giá trị phân biệt: 1, 2, 3.

a) Hãy chỉ ra một cách ghi thỏa mãn các điều kiện trên.

b) Trong các cách ghi thỏa mãn các điều kiện trên, tìm cách ghi có tổng bình phương của các số ở bốn đỉnh là nhỏ nhất.','2026-10-12T06:27:53.216263+00:00','2026-10-12T06:27:53.216263+00:00','2026-10-12T06:27:53.216263+00:00','[{"id": "q1", "label": "Câu 2", "text": "Câu 2 (1.5 điểm). Người ta muốn ghi bốn số thực ở bốn đỉnh của hình vuông $ABCD$ (mỗi đỉnh một số) thỏa mãn:\n\ni) Bốn số được ghi là đối một phân biệt;\n\nii) Tổng hai số được ghi ở hai đầu của cạnh $AB$ là 0;\n\niii) Tổng hai số được ghi ở hai đầu của ba cạnh còn lại là ba giá trị phân biệt: 1, 2, 3.\n\na) Hãy chỉ ra một cách ghi thỏa mãn các điều kiện trên.\n\nb) Trong các cách ghi thỏa mãn các điều kiện trên, tìm cách ghi có tổng bình phương của các số ở bốn đỉnh là nhỏ nhất."}]');
INSERT INTO scans (id,owner_id,status,source,image_key,image_content_type,image_bytes,image_width,image_height,problem_text,created_at,updated_at,confirmed_at,questions_json) VALUES ('0db2dc2c-15e5-4723-905a-ed1d1909886a','57bd23d6826d75c0bb806b0540cf6866bd607e325243e246cbee905c7b52d98a','confirmed','library','game-theory-02/no-upload/0db2dc2c-15e5-4723-905a-ed1d1909886a','image/png',1,1,1,'Câu 5 (1.5 điểm). Cho bảng ô vuông kích thước $2 \times 9$ và số nguyên đường $k \leq 18$. Hai ô của bảng được gọi là kế bến nếu chứng có một cạnh chung. Hai bạn An và Bình chơi trò "Truy Tìm Tàu Ngầm" như sau: Trước khi trò chơi bắt đầu, An chọn một ô trên bảng và không cho Bình biết. Ở mỗi lượt chơi:

- An phải chọn một ô mới, kề bên với ô đã chọn trước đó, và không cho Bình biết;
- Sau khi An chọn xong, Bình chọn kô của bảng và hỏi An: trong kô này có ô An vừa chọn hay không? Nếu có thì Bình thắng, nếu không thì hai bạn lại chơi lượt tiếp theo.

a) Xét k = 4. Chứng minh rằng Bình có thể thắng sau không quá 8 lượt chơi.

b) Xét k = 2. Chứng minh rằng Bình có thể thắng sau không quá 16 lượt chơi.','2026-10-12T06:27:53.216263+00:00','2026-10-12T06:27:53.216263+00:00','2026-10-12T06:27:53.216263+00:00','[{"id": "q1", "label": "Câu 5", "text": "Câu 5 (1.5 điểm). Cho bảng ô vuông kích thước $2 \\times 9$ và số nguyên đường $k \\leq 18$. Hai ô của bảng được gọi là kế bến nếu chứng có một cạnh chung. Hai bạn An và Bình chơi trò \"Truy Tìm Tàu Ngầm\" như sau: Trước khi trò chơi bắt đầu, An chọn một ô trên bảng và không cho Bình biết. Ở mỗi lượt chơi:\n\n- An phải chọn một ô mới, kề bên với ô đã chọn trước đó, và không cho Bình biết;\n- Sau khi An chọn xong, Bình chọn kô của bảng và hỏi An: trong kô này có ô An vừa chọn hay không? Nếu có thì Bình thắng, nếu không thì hai bạn lại chơi lượt tiếp theo.\n\na) Xét k = 4. Chứng minh rằng Bình có thể thắng sau không quá 8 lượt chơi.\n\nb) Xét k = 2. Chứng minh rằng Bình có thể thắng sau không quá 16 lượt chơi."}]');
